///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_userlist_oncelldblclick
 * @description 파일 더블클릭
 * @param {Number} row 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} colid 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_userlist_oncelldblclick = function (row, columnIndex, colid) {
    try {
        if (dlt_selectOneFilesRes.getRowStatus(dlt_selectOneFilesRes.getRowPosition()) === "R") { // R: 불러오기, C: 신규삽입
            scwin.filedown(dlt_selectOneFilesRes.getCellData(row, "attachFileSeq"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.grd_userlist_oncelldblclick" });
    }
};

/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        const filenm = file_name.getValue();
        if (scwin.notiId === "input") {
            dlt_selectOneFilesRes.setCellData(dlt_selectOneFilesRes.getRowPosition(), "fileInfo", inf_find.getValue());
            dlt_selectOneFilesRes.setCellData(dlt_selectOneFilesRes.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dlt_selectOneFilesRes.setCellData(dlt_selectOneFilesRes.getRowPosition(), "fileInfo", inf_find.getValue());
            // dlt_selectOneFilesRes.NameString(dlt_selectOneFilesRes.rowposition, "ATTACH_SEQ") = dlt_selectOneFilesRes.rowposition;
            file_name.setValue(inf_find.getValue());
        }
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.inf_find_OnClick" });
    }
};

