/**
 * @method
 * @name muc_ondone
 * @description 첨부파일 업로드 submitdone
 * @param {*} data 셀 값(원본 데이터)
 * @returns {void}
 * @hidden N
 */
scwin.muc_ondone = function(data) {
};

/**
 * @method
 * @name muc_onprogress
 * @description 파일업로드 후 저장 처리
 * @param {*} data 셀 값(원본 데이터)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.muc_onprogress = async function (data) {
    try {

        $c.win.alert($c.data.getMessage("com_complete_0150", "첨부파일등록"));
        $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.muc_onprogress" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 행 삭제 — 「행삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
        const point = dlt_selectOneFilesRes.getRowPosition();

        muc.removeFile(dlt_selectOneFilesRes.getCellData(point, "attachFileNm"));
        dlt_selectOneFilesRes.removeRow(point);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description 닫기 버튼
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        // await $c.win.closePopup(); //self.close();
        $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.btn_close_onclick" });
    }
};

/**
 * @method
 * @name btn_modify_onclick
 * @description 수정 버튼 — 「수정」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_modify_onclick = function (e) {
    try {
        scwin.save("수정");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.btn_modify_onclick" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 삭제 버튼 — 「삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_delete_onclick = function (e) {
    try {
        scwin.delete();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 저장 버튼 — 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_save_onclick = function (e) {
    try {
        scwin.save("저장");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.btn_save_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description 첨부파일 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    // trs_Read.Action = "/ListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readFile&acpt_no=" + scwin.strAcptNo;
    // trs_Read.KeyValue = "JSP(O:pOutput2=dlt_selectOneFilesRes)";
    // trs_Read.Post();

    dma_selectOneFilesReq.set("acptNo", scwin.strAcptNo);
    const sbmOptions = {
        id: "sbm_selectOneFiles",
        action: "/api/listing/lstproc/kospi-appl-attach/select-one-files",
        method: "get",
        ref : "dma_selectOneFilesReq",
        target : "dlt_selectOneFilesRes=body",
        isProcessMsg : true
    };
    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_depupcode_submitdone(sbmRtn);
};

/**
 * @method
 * @name sbm_depupcode_submitdone
 * @description 첨부파일 목록 조회 완료
 * @returns {void}
 * @hidden N
 */
scwin.sbm_depupcode_submitdone = function() {
    if(dlt_selectOneFilesRes.getRowCount() > 0) {
        btn_save.setDisabled(true);
        btn_modify.setDisabled(false);
    } else {
        btn_save.setDisabled(false);
        btn_modify.setDisabled(true);
    }
}

/**
 * @method
 * @name delete
 * @description 선택 자료를 삭제한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    let rtn = await $c.win.confirm('첨부파일을 삭제 하시겠습니까?');
    if (rtn) { // [확인] 버튼이 눌려졌을 경우
        for (i = 0; i <= dlt_selectOneFilesRes.getRowCount(); i++) {
            dlt_selectOneFilesRes.removeRows(i);
        }
        // trs_Delete.Action = "/ListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&method=removeFile&acpt_no=" + scwin.strAcptNo;
        // trs_Delete.KeyValue = "JSP(I:pInput=dlt_selectOneFilesRes)";
        // trs_Delete.Post();

        dma_selectOneFilesReq.set("acptNo", scwin.strAcptNo);
        const sbmOptions = {
            id: "sbm_delete",
            action: "/api/listing/lstproc/kospi-appl-attach/delete",
            method: "post",
            ref : "dma_selectOneFilesReq",
            // target : "dlt_selectOneFilesRes=body",
            isProcessMsg : true
        };
        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        await scwin.sbm_delete_submitdone(sbmRtn);
    }
};

/**
 * @method
 * @name sbm_delete_submitdone
 * @description 파일 삭제 완료
 * @returns {void}
 * @hidden N
 */
scwin.sbm_delete_submitdone = function() {
    $c.win.alert($c.data.getMessage("com_complete_0150", "첨부파일삭제"));
    $c.win.closePopup();
}

/**
 * @method
 * @name filedown
 * @description 파일 다운로드
 * @param {*} attach_seq attach_seq
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(attach_seq) {
    // location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08
    // + "&file_id=" + scwin.strAcptNo + "&attach_seq=" + attach_seq + "&gubun=32";

    dma_fileDownloadReq.set("fileId", scwin.strAcptNo);
    dma_fileDownloadReq.set("attachSeq", attach_seq);
    dma_fileDownloadReq.set("gubun", "32");
    const sbmOptions = {
        id: "sbm_fileDownload",
        action: "/api/listing/common/file/file-download",
        method: "get",
        ref : "dma_fileDownloadReq",
        // target : "dlt_selectOneFilesRes=body",
        // submitDoneHandler : scwin.sbm_depupcode_submitdone,
        isProcessMsg : true
    };
    $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name selectCallback
 * @description 파일업로드시 파일정보 그리드 데이터셋에 저장
 * @returns {void}
 * @hidden N
 */
scwin.selectCallback = function() {

    let fileInfos = "";
    fileInfos = muc.getFileInfos();

    dlt_selectOneFilesRes.removeAll();
    dlt_selectOneFilesRes.setBroadcast(false);
    for (i = 0; i < fileInfos.length; i++ ) {
        dlt_selectOneFilesRes.insertRow();
        dlt_selectOneFilesRes.setCellData(i, "attachFileSeq", i+1);
        dlt_selectOneFilesRes.setCellData(i, "attachFileNm", fileInfos[i].name);
    }
    dlt_selectOneFilesRes.setBroadcast(true, true);
}

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name save
 * @description 입력값을 저장한다.
 * @param {String} type 구분 값
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function(type) {
    dlt_selectOneFilesRes.setBroadcast(false);
    for (i = 0; i <= dlt_selectOneFilesRes.getRowCount(); i++) {
        if (dlt_selectOneFilesRes.getCellData(i, "attachFileSeq") === "" && dlt_selectOneFilesRes.getCellData(i, "attachFileNm") === "") {
            dlt_selectOneFilesRes.removeRow(i)
        }
    }
    dlt_selectOneFilesRes.setBroadcast(true, true);
    if (dlt_selectOneFilesRes.getRowCount() === 0) {
        $c.win.alert("첨부파일을 한개이상 입력해주세요.");
        return;
    }
    let rtn = await $c.win.confirm($c.data.getMessage("com_crud_0198", type));
    if (rtn) {
        // [확인] 버튼이 눌려졌을 경우
        // trs_Update.Action = "/ListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=modifyFile&acpt_no=" + scwin.strAcptNo + "&usr_id=" + scwin.gUsrId;
        // trs_Update.KeyValue = "JSP(I:pInput2=dlt_selectOneFilesRes)";
        // trs_Update.Post();

        muc.changeAction("/api/listing/lstproc/kospi-appl-attach/insert"); // action 설정
        muc.setParam(0, "acptNo", scwin.strAcptNo);	// 상장심사게시판구분코드
        muc.startUpload();
    }
};
